type Book struct {
    authorID int64
    author   func() (*Author, error)
}

func NewBook(authorID int64, gw Gateway) *Book {
    return &Book{authorID, sync.OnceValues(func() (*Author, error) {
        return gw.FindAuthor(authorID)   // runs once; error is cached too
    })}
}

func (b *Book) Author() (*Author, error) { return b.author() }

func (b *Book) Author() (*Author, error) {
    b.mu.Lock()
    defer b.mu.Unlock()
    if !b.loaded {
        a, err := b.load()
        if err != nil { return nil, err }   // failure not cached
        b.author, b.loaded = a, true
    }
    return b.author, nil
}

